repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('pia', 39), ('noor', 37), ('mia', 28), ('pia', 25), ('mia', 47)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.sequence.py:
"""Codes of donations in order."""


def ranked_codes(donations):
    """Return the pounds of each donation as a text code, from the lowest number to the highest."""
    return sorted(str(x.pounds) for x in donations)


def code_of(donation):
    """Return the text code of one donation."""
    return str(donation.pounds)


def largest_pounds(donations):
    """Return the largest pounds, or None when there are no donations."""
    values = [x.pounds for x in donations]
    return max(values) if values else None


def donor_names(donations):
    """Return the distinct donor values, in first-seen order."""
    names = []
    for x in donations:
        if x.donor not in names:
            names.append(x.donor)
    return names

repo.tests/test_visible.py:
from donations import Donation
from sequence import ranked_codes


def test_nine_before_ten():
    assert ranked_codes([Donation("a", 10), Donation("b", 9)]) == ["9", "10"]


def test_single_digits():
    assert ranked_codes([Donation("a", 3), Donation("b", 1), Donation("c", 2)]) == ["1", "2", "3"]
